            rw.Int32(ref U50);
            rw.Single(ref U51);
            rw.Int32(ref U52);
            rw.Int32(ref U53);
            rw.Single(ref U54);
            rw.Int32(ref U55);
            rw.Int32(ref U56);
            rw.Single(ref U57);
            rw.Int32(ref U58);
            rw.Int32(ref U59);
