    internal override IChunk? NewChunk(uint chunkId) => chunkId switch
    {
        0x090EF000 => new Chunk090EF000(),
        0x090EF001 => new Chunk090EF001(),
        0x090EF002 => new Chunk090EF002(),
        0x090EF003 => new Chunk090EF003(),
        0x090EF004 => new Chunk090EF004(),
